// Scenario-based quiz questions, batch b.
const m = (id, c, l, q, o, a, e) => ({ id, c, l, q, o, a, e });

export const MCQ_B = [
  // ---------- EF Core and SQL Server ----------
  m("cb01", "efsql", "j",
    "An endpoint returns 50 orders with customer names. Logs show 51 SQL queries: one for `Orders`, then one `SELECT ... FROM Customers WHERE Id = @p0` per order. The code loops over the orders and reads `o.Customer.Name`, and lazy-loading proxies are enabled. Which change fixes the root cause?",
    ["Add an index on `Orders.CustomerId` so each customer lookup is cheaper",
     "Call `ToListAsync()` on the orders query before the loop starts",
     "Project with `Select(o => new { o.Id, o.Customer.Name })` so one joined query is issued",
     "Increase the connection pool size so the per-order queries run in parallel"],
    2,
    "The extra queries come from lazy loading touching a navigation property inside a loop (the N+1 problem); a projection or `Include(o => o.Customer)` makes EF generate a single JOIN. An index makes each lookup cheaper but you still pay 51 round trips, and materializing only the orders with `ToListAsync()` does not load the customers."),
  m("cb02", "efsql", "j",
    "A read-only product list endpoint loads 20,000 rows with `db.Products.ToListAsync()` and maps them to DTOs. Nothing is modified or saved. Memory use and latency are high because EF keeps a snapshot of every entity. What is the simplest EF Core change that reduces this overhead?",
    ["Add `AsNoTracking()` to the query because the entities are never updated",
     "Set `ChangeTracker.AutoDetectChangesEnabled = true` before running the query",
     "Wrap the query in a `TransactionScope` so the rows are read in one batch",
     "Replace `ToListAsync()` with `ToList()` to avoid async state machine overhead"],
    0,
    "`AsNoTracking()` skips identity resolution and snapshot creation, which is exactly the cost in a read-only query. `AutoDetectChangesEnabled` is already true by default and is about detecting edits, and a transaction or sync call does not change how many entities are tracked."),
  m("cb03", "efsql", "m",
    "A query `db.Blogs.Include(b => b.Posts).Include(b => b.Tags)` returns one blog with 200 posts and 50 tags. The generated single SQL query returns 10,000 rows with the blog columns duplicated on each, and the endpoint is slow. Which EF Core feature addresses this cartesian explosion?",
    ["`AsNoTrackingWithIdentityResolution()`, which collapses the duplicated rows in SQL",
     "`AsSplitQuery()`, which issues a separate SQL query for each collection include",
     "`ThenInclude()`, which joins both collections in a single pass over the blog",
     "`AsNoTracking()`, which removes duplicate rows from the result set"],
    1,
    "`AsSplitQuery()` sends one query per collection so the row count is 200 + 50 instead of 200 x 50. The trade-off is extra round trips and, without a surrounding transaction, possibly inconsistent data between the queries. Identity resolution only affects how entities are built client-side; the duplicated rows still travel over the wire."),
  m("cb04", "efsql", "m",
    "Two admins open the same `Product` edit page and both click Save. The second save silently overwrites the first admin's price change. The entity has no concurrency configuration. What should you add so EF Core detects the conflict?",
    ["Run `SaveChanges()` inside a `Serializable` transaction for every update",
     "Mark `Price` as `IsRequired()` so conflicting values fail validation",
     "Add a unique index on `Product.Name` so conflicting writes are rejected",
     "Add a `rowversion` property configured with `IsRowVersion()` and handle `DbUpdateConcurrencyException`"],
    3,
    "A concurrency token makes EF add `WHERE RowVersion = @original` to the UPDATE, and zero affected rows raises `DbUpdateConcurrencyException`, which you resolve by reloading or merging. A Serializable transaction does not help because the two admins read the entity in separate earlier requests, long before the update transaction starts."),
  m("cb05", "efsql", "m",
    "You must set `Status = 'Archived'` on about 2 million orders older than five years. Loading entities and calling `SaveChanges` is far too slow. On EF Core 7 or later, what does `ExecuteUpdateAsync` do?",
    ["It sends one set-based `UPDATE` without loading entities and bypasses the change tracker",
     "It loads entities in batches of 1,000 and still raises `SavingChanges` for each one",
     "It updates already tracked entities in memory so later reads show the new status",
     "It queues the update and runs it as part of the next `SaveChanges()` call"],
    0,
    "`ExecuteUpdateAsync` translates directly to a single `UPDATE ... WHERE` and runs immediately, so no entities are materialized and no change-tracking events fire. Because it bypasses the tracker, any entity of the same rows that is already tracked becomes stale; it is not deferred to `SaveChanges`."),
  m("cb06", "efsql", "m",
    "A query filters `WHERE TenantId = @t AND CreatedAt >= @from ORDER BY CreatedAt` on a table with 100 million rows. Every call has an equality on `TenantId` and a range on `CreatedAt`. Which composite index serves this query best?",
    ["`(CreatedAt, TenantId)`, because the more selective column must always come first",
     "Two separate single-column indexes, which SQL Server always intersects efficiently",
     "`(TenantId, CreatedAt)`, so it seeks the tenant and then reads the date range in order",
     "`(TenantId)` only, because a range column in the key makes the index unusable"],
    2,
    "Put equality columns first and the range column after: the seek lands on the tenant and the matching rows are already sorted by `CreatedAt`, so no sort is needed. 'Most selective first' is a rule of thumb that breaks down once a range predicate and an ORDER BY are involved, and index intersection is occasional, not guaranteed."),
  m("cb07", "efsql", "m",
    "`SELECT OrderId, Status, Total FROM Orders WHERE CustomerId = @c` seeks on `IX_Orders_CustomerId`, but the plan shows a Key Lookup that is 90% of the cost for 5,000 matching rows. Which index change removes the lookups?",
    ["Make `IX_Orders_CustomerId` clustered so every column is stored in its key",
     "Recreate the index with `INCLUDE (Status, Total)` so it covers the query",
     "Add `OPTION (FORCE ORDER)` so the optimizer skips the lookups",
     "Rebuild the index with `FILLFACTOR = 100` so the columns fit on its leaf pages"],
    1,
    "A covering index with `INCLUDE (Status, Total)` stores the extra columns on the leaf level, so the query is answered from the index alone. Making it clustered is not possible when the table already has a clustered key (usually the PK), and a clustered key would not be the right fix anyway. Fill factor controls free space, not which columns are stored."),
  m("cb08", "efsql", "s",
    "A procedure `GetOrders @CustomerId` takes 5 ms for most customers but 40 s for one very large customer. After `EXEC sp_recompile 'GetOrders'` the large customer is fast, but then other customers become slow. What is the most likely cause?",
    ["Statistics are never updated automatically on tables above one million rows",
     "The large customer's rows live in a different filegroup that reads more slowly",
     "SQL Server recompiles the procedure on every call and picks a bad plan for that customer",
     "The plan cached for the first parameter value is reused for very different data (parameter sniffing)"],
    3,
    "The plan is compiled using the parameter values of the first call and then cached, so a plan good for a small customer (seeks and lookups) is terrible for a huge one, and vice versa. Mitigations include `OPTION (RECOMPILE)`, `OPTIMIZE FOR`, or splitting the logic. Recompiling on every call would give each customer a fitting plan, which is the opposite of the symptom."),
  m("cb09", "efsql", "s",
    "Reports under the default `READ COMMITTED` level in SQL Server block order inserts because the readers wait on exclusive locks and writers wait on shared locks. You want readers and writers not to block each other without rewriting queries. What is a suitable change?",
    ["Enable `READ_COMMITTED_SNAPSHOT` on the database so reads use row versions instead of shared locks",
     "Run the reports under `READ UNCOMMITTED` so they get a consistent snapshot without locking",
     "Run everything under `SERIALIZABLE` so transactions queue in order and never block",
     "Add `NOLOCK` hints to the writers so inserts skip taking exclusive locks"],
    0,
    "`READ_COMMITTED_SNAPSHOT` makes the default level read the last committed row version from the version store, so readers neither block nor are blocked by writers, at the cost of tempdb/version-store overhead. `READ UNCOMMITTED` avoids shared locks but allows dirty reads, so it does not give consistent data, and `SERIALIZABLE` increases blocking."),
  m("cb10", "efsql", "s",
    "Production logs show error 1205: Transaction was chosen as the deadlock victim. Transaction A updates `Orders` then `Inventory`; transaction B updates `Inventory` then `Orders` for overlapping rows. Which fix addresses the root cause?",
    ["Raise `LOCK_TIMEOUT` so each transaction waits longer for the other to finish",
     "Merge both updates into one larger transaction so the lock graph is simpler",
     "Make both code paths access tables and rows in the same order, and retry the victim on 1205",
     "Run both transactions under `READ UNCOMMITTED` so neither takes locks"],
    2,
    "Deadlocks need a cycle of waits, and a consistent access order removes the cycle; retrying the victim handles the rare remaining cases. A longer lock timeout just prolongs the cycle (the deadlock monitor already breaks it), and `READ UNCOMMITTED` only affects shared locks, so two writers still take exclusive locks and can still deadlock."),
  m("cb11", "efsql", "m",
    "A feed uses `ORDER BY Id DESC OFFSET @n ROWS FETCH NEXT 50 ROWS ONLY`. Pages near offset 5,000,000 are very slow, and users see duplicate rows when new items arrive while they scroll. What approach fixes both problems?",
    ["Add a nonclustered index on `Id` so that `OFFSET` can skip rows instantly",
     "Use keyset pagination: `WHERE Id < @lastId ORDER BY Id DESC` with the last key seen",
     "Cache the total row count so the server avoids the `OFFSET` scan",
     "Increase the page size to 5,000 so fewer deep pages are requested"],
    1,
    "Keyset (seek) pagination jumps straight to the position with an index seek, so cost stays flat for deep pages, and anchoring on the last seen key means inserts do not shift the window. `OFFSET` must still read and discard all skipped rows even with an index, and a bigger page size does nothing for the shifting-window duplicates."),
  m("cb12", "efsql", "m",
    "Auditors ask what a `Contracts` row looked like on 1 March, and you want this answer without writing custom audit code. On SQL Server 2016 or later, which feature provides it?",
    ["Change Data Capture, queried with `AS OF` against the live table",
     "A `rowversion` column, which stores the previous values of each updated row",
     "Snapshot isolation, which keeps old row versions available for later queries",
     "A system-versioned temporal table, queried with `FOR SYSTEM_TIME AS OF '2026-03-01'`"],
    3,
    "A system-versioned temporal table keeps a history table automatically and supports point-in-time queries with `FOR SYSTEM_TIME`. `rowversion` is only a counter that changes on update, and snapshot isolation's version store is transient (used for running transactions), not an audit history."),
  m("cb13", "efsql", "m",
    "`SELECT * FROM Orders WHERE YEAR(CreatedAt) = 2025` scans the whole table even though `CreatedAt` has an index. Which rewrite lets SQL Server seek on that index?",
    ["`WHERE CreatedAt >= '2025-01-01' AND CreatedAt < '2026-01-01'`",
     "`WHERE CONVERT(varchar(4), CreatedAt, 120) = '2025'`",
     "`WHERE YEAR(CreatedAt) = 2025` with a `WITH (FORCESEEK)` table hint",
     "`WHERE DATEPART(year, CreatedAt) IN (2025)`"],
    0,
    "Wrapping the column in a function makes the predicate non-sargable, so the index key cannot be used for a seek; comparing the bare column against a half-open range makes it sargable. The `CONVERT` and `DATEPART` versions are the same problem in different clothes, and a hint cannot change that the predicate is not on the index key."),
  m("cb14", "efsql", "j",
    "A developer writes `db.Orders.AsEnumerable().OrderByDescending(o => o.Total).Take(10).ToList()` on a table with 10 million rows. What happens?",
    ["EF translates the ordering and `Take` to SQL because the query is still composed on the `DbSet`",
     "EF throws because `AsEnumerable` cannot be called on a `DbSet`",
     "All rows are transferred to the app, where the ordering and `Take` run in memory",
     "EF caches the table in the change tracker once, so later calls are fast"],
    2,
    "`AsEnumerable()` switches from `IQueryable` to LINQ-to-Objects, so everything after it executes in memory and the whole table is read first. Keep `OrderByDescending` and `Take` before the switch (or avoid `AsEnumerable`) so they translate to `ORDER BY ... TOP`. Nothing is cached for later calls."),
  m("cb15", "efsql", "m",
    "A dashboard action runs `await Task.WhenAll(GetOrdersAsync(), GetCustomersAsync())`, and both methods use the same scoped `DbContext`. It intermittently throws 'A second operation was started on this context instance before a previous operation completed.' What is the correct fix?",
    ["Register `DbContext` as a singleton so the same instance is shared across tasks",
     "Run the calls sequentially, or give each parallel call its own context from `IDbContextFactory`",
     "Call `EnableThreadSafetyChecks(false)` so concurrent operations are allowed",
     "Wrap both calls in a `lock` so only one thread touches the context at a time"],
    1,
    "`DbContext` is not thread-safe and does not support parallel operations on one instance, so use one context per concurrent operation or await calls one after another. Disabling the safety check just hides the exception and risks corrupted state, a singleton makes it worse, and a `lock` does not work across `await` boundaries."),
  m("cb16", "efsql", "m",
    "Code does `db.Add(order); await db.SaveChangesAsync(); db.Add(payment); await db.SaveChangesAsync();`. When the second save fails, the order is still committed. Which approach makes both writes atomic?",
    ["Call `SaveChangesAsync(acceptAllChangesOnSuccess: false)` on the first save",
     "Catch the exception and delete the order when the second save throws",
     "Rely on EF Core's default, which wraps consecutive saves on one context in a single transaction",
     "Begin a transaction with `BeginTransactionAsync()` around both saves, or add both and call `SaveChangesAsync` once"],
    3,
    "Each `SaveChanges` call runs in its own transaction, so you need either one `SaveChanges` for both entities or an explicit transaction that you commit at the end. `acceptAllChangesOnSuccess` only controls whether the change tracker resets its state, and compensating by deleting is not atomic (the order is briefly visible and the delete can fail)."),
  m("cb17", "efsql", "s",
    "After enabling `EnableRetryOnFailure()` for Azure SQL, this code throws 'The configured execution strategy does not support user-initiated transactions': `await using var tx = await db.Database.BeginTransactionAsync(); ...`. What is the correct fix?",
    ["Wrap the whole unit, with the transaction inside, in `db.Database.CreateExecutionStrategy().ExecuteAsync(...)`",
     "Disable retries globally because transient failures are rare in Azure SQL",
     "Replace `BeginTransactionAsync` with a `TransactionScope` using default settings",
     "Set `CommandTimeout` to 0 so the strategy never has to retry the transaction"],
    0,
    "A retrying strategy must be able to re-run the entire unit of work, so you hand it the whole transaction as a delegate and it restarts from the beginning after a transient failure. Disabling retries throws away resilience, and a plain `TransactionScope` hits the same limitation because the strategy still cannot replay it."),
  m("cb18", "efsql", "s",
    "An `Orders` table uses a client-generated `Guid.NewGuid()` clustered primary key. Under heavy inserts, page splits and fragmentation climb and throughput drops. What is the best fix that keeps GUID keys?",
    ["Store the key as `NVARCHAR(36)`, which sorts sequentially as text",
     "Run `ALTER INDEX REORGANIZE` nightly, which removes the cause of the page splits",
     "Generate sequential GUIDs (`NEWSEQUENTIALID()` or EF Core's sequential GUID generator) so inserts append to the index end",
     "Rebuild the clustered index with `FILLFACTOR = 100` so pages are packed tightly"],
    2,
    "Random keys insert into the middle of the clustered index, forcing page splits; sequential GUIDs keep inserts at the end. Maintenance like REORGANIZE only treats the fragmentation after the fact, and a 100% fill factor leaves no free space so random inserts split pages even more."),

  // ---------- Snowflake ----------
  m("cb19", "snowflake", "m",
    "An XL virtual warehouse is used by analysts from 9 to 5, but billing shows credits consumed around the clock. The warehouse has `AUTO_SUSPEND = 0`. Which change most directly stops idle spend while keeping it available on demand?",
    ["Resize it to X-Small, since smaller warehouses stop billing when idle",
     "Set `AUTO_SUSPEND` to about 60 seconds and keep `AUTO_RESUME = TRUE`",
     "Drop the warehouse each evening and recreate it each morning",
     "Disable the result cache so queries stop reserving compute overnight"],
    1,
    "A running warehouse bills credits per second whether or not it executes queries, so auto-suspend after a short idle period plus auto-resume gives on-demand compute with no idle cost. Resizing only lowers the hourly rate, and the result cache is unrelated to warehouse billing."),
  m("cb20", "snowflake", "m",
    "A teammate wants to create an index on `event_date` in Snowflake to speed up date filters on a large table. How does Snowflake normally skip data for such filters?",
    ["It maintains B-tree indexes on every column automatically",
     "It reads every partition but caches the results of earlier filters",
     "It requires partitions to be declared in DDL, such as `PARTITION BY RANGE`",
     "It stores min/max metadata per column for each micro-partition and prunes those that cannot match"],
    3,
    "Snowflake data is stored in immutable columnar micro-partitions, each with metadata such as min/max values per column, and the optimizer prunes partitions whose ranges cannot satisfy the filter. Standard tables have no user-defined indexes or manual partitions; pruning effectiveness depends on how well the data is ordered."),
  m("cb21", "snowflake", "s",
    "A multi-terabyte `EVENTS` table is almost always filtered on `event_date`, but data arrives out of date order. `SYSTEM$CLUSTERING_INFORMATION` shows high clustering depth and queries scan most partitions. What is a reasonable fix and its trade-off?",
    ["Define a clustering key on `event_date`, accepting background reclustering credits and storage",
     "Create a secondary index on `event_date`, accepting slower inserts",
     "Increase the warehouse size, which makes Snowflake re-sort micro-partitions at query time",
     "Run `OPTIMIZE` weekly, which compacts files by the filter column"],
    0,
    "A clustering key co-locates similar `event_date` values in the same micro-partitions so pruning works, and Automatic Clustering consumes credits to maintain it, which is why it suits large, frequently filtered tables. Snowflake has no secondary indexes for standard tables, and `OPTIMIZE` is a Delta Lake command, not Snowflake."),
  m("cb22", "snowflake", "m",
    "On an Enterprise-edition account with default settings, someone ran `DELETE FROM orders;` without a WHERE clause 20 minutes ago on a permanent table. What is the fastest safe way to get the data back?",
    ["Open a support case, because only Fail-safe can restore deleted rows",
     "Run `UNDROP TABLE orders`, which reverses row deletions",
     "Run `CREATE TABLE orders_restore CLONE orders AT(OFFSET => -60*30)`, then copy or swap the data back",
     "Restore from the last scheduled snapshot taken by the virtual warehouse"],
    2,
    "Time Travel (default retention 1 day for permanent tables) lets you query or clone the table as it was before the delete, and cloning is metadata-only and instant. `UNDROP` only restores dropped objects, not deleted rows, and Fail-safe is a last-resort Snowflake-side recovery, not for self-service."),
  m("cb23", "snowflake", "j",
    "A team runs `CREATE DATABASE dev CLONE prod` on a 5 TB production database. Finance asks how much extra storage the clone consumes right after it is created. What is the accurate answer?",
    ["About 5 TB, since the clone copies every micro-partition",
     "Almost none at first, since it references the same micro-partitions and only later changes add storage",
     "About 2.5 TB, since clones are stored compressed at half size",
     "None ever, because changes made in the clone are written back to the source"],
    1,
    "A zero-copy clone is a metadata operation that points at the existing micro-partitions; storage grows only as data in the clone or source diverges. Clones are independent after creation, so changes in the clone do not affect the source."),
  m("cb24", "snowflake", "s",
    "A stream on `RAW_ORDERS` is used in two ways: an analyst runs `SELECT * FROM raw_orders_stream` for debugging, and a task runs `INSERT INTO orders_clean SELECT ... FROM raw_orders_stream`. Which statement about the stream offset is accurate?",
    ["Both statements advance the offset because they read from the stream",
     "Neither advances it, because the offset moves only when the task is resumed",
     "Only the `SELECT` advances it, since DML cannot read from streams",
     "Only the committed DML that consumes the stream (the `INSERT`) advances it, while a plain `SELECT` does not"],
    3,
    "A stream's offset advances only when its contents are consumed by a DML statement (for example INSERT, MERGE or CTAS) in a transaction that commits; querying it does not consume the changes. That lets you inspect a stream safely, but also means a failed task leaves the changes available for the next run."),
  m("cb25", "snowflake", "s",
    "At 9 AM, 60 dashboard queries (about 2 seconds each) queue on a Medium warehouse, though each runs fine alone. At night one heavy ETL query takes 40 minutes on the same size. What is the right fix for each?",
    ["Multi-cluster warehouse for the dashboards (concurrency); a larger size for the ETL (single-query speed)",
     "A larger warehouse for the dashboards; a multi-cluster warehouse for the ETL",
     "Multi-cluster for both, since extra clusters speed up a single query by splitting it",
     "A larger warehouse for both, since size determines how many queries run concurrently"],
    0,
    "Queuing under many small queries is a concurrency problem solved by adding clusters, while one long complex query benefits from more compute per query, meaning a larger size. A single query runs on one cluster, so extra clusters do not speed it up."),
  m("cb26", "snowflake", "m",
    "Finance wants Snowflake to stop warehouses from using more than 500 credits a month, not merely warn someone. Which configuration does this?",
    ["A resource monitor with only a `NOTIFY` trigger at 100 percent",
     "`STATEMENT_TIMEOUT_IN_SECONDS` set to 3600 on the account",
     "A resource monitor with a `SUSPEND` or `SUSPEND_IMMEDIATE` trigger at 100 percent",
     "`MAX_CLUSTER_COUNT` set to 1 on every warehouse"],
    2,
    "A resource monitor with a suspend action at the quota stops the assigned warehouses (`SUSPEND` lets running queries finish, `SUSPEND_IMMEDIATE` cancels them). `NOTIFY` only sends an alert and a statement timeout limits single queries, not total monthly credits."),

  // ---------- Microservices and messaging ----------
  m("cb27", "micro", "m",
    "A payment consumer on a broker with at-least-once delivery occasionally receives the same `PaymentCaptured` message twice after a network blip, and a customer gets two receipts. What is the correct way to handle this?",
    ["Switch to `autoAck` so the broker never redelivers a message",
     "Reduce the prefetch count to 1 so duplicates cannot occur",
     "Add retry with backoff in the consumer so duplicates are suppressed",
     "Make the consumer idempotent by recording processed message ids under a unique constraint and skipping repeats"],
    3,
    "At-least-once delivery means duplicates are expected, so consumers must tolerate them, typically with an inbox table or natural idempotency. `autoAck` removes redelivery by trading to at-most-once (messages can be lost), and prefetch or retry settings do not prevent duplicate deliveries."),
  m("cb28", "micro", "m",
    "A RabbitMQ consumer uses `autoAck: true`. During a deploy the process is killed while handling 30 messages, and after restart those orders are never processed. Which change prevents this loss?",
    ["Declare the queue as transient so messages are re-created on restart",
     "Use manual acknowledgements and call `BasicAck` only after the work completes",
     "Increase `x-message-ttl` so unprocessed messages stay in the queue longer",
     "Enable publisher confirms on the producer so delivered messages are kept"],
    1,
    "With auto-ack the broker considers a message done as soon as it is delivered, so a crash mid-processing loses it; manual acks let the broker redeliver anything not acknowledged. Publisher confirms protect the producer-to-broker hop, not the broker-to-consumer hop."),
  m("cb29", "micro", "m",
    "A malformed message makes a consumer throw. The consumer calls `BasicNack(tag, false, requeue: true)`, so the message is redelivered immediately and forever, pegging CPU and starving other messages. What is the recommended handling?",
    ["Reject with `requeue: false` and configure a dead-letter exchange so poison messages go to a DLQ",
     "Always `BasicAck` on exceptions so that the message disappears",
     "Put the queue in lazy mode so that the redelivery loop is slower",
     "Add more consumers so someone eventually processes it successfully"],
    0,
    "A poison message never succeeds, so it should be rejected without requeue and routed to a dead-letter queue for inspection and possible replay (often after a limited number of retries). Acking on error silently drops the data, and extra consumers just multiply the failing loop."),
  m("cb30", "micro", "m",
    "An `orders` Kafka topic has 12 partitions, and events for the same order sometimes get processed out of order (`OrderShipped` before `OrderPaid`). Producers send with a null key. How do you guarantee per-order ordering?",
    ["Increase the partition count so each order gets its own partition",
     "Add more consumers to the group so processing keeps up with production",
     "Publish with the order id as the message key so all events for an order go to one partition",
     "Set `acks=all` so Kafka serializes writes across partitions"],
    2,
    "Kafka guarantees order only within a partition, and records with the same key are hashed to the same partition, so keying by order id preserves each order's sequence. More partitions or consumers do not create cross-partition ordering, and `acks` controls durability, not ordering across partitions."),
  m("cb31", "micro", "m",
    "A consumer group has 10 instances reading a topic with 6 partitions, and lag keeps growing. A teammate scales out to 14 instances. What happens?",
    ["Throughput rises because Kafka splits partitions among instances by offset range",
     "Lag drops because extra instances read the same partitions in parallel",
     "Kafka automatically adds partitions to match the number of consumers",
     "Nothing improves, since within a group each partition is read by at most one consumer and the extras sit idle"],
    3,
    "Parallelism in a consumer group is capped by the partition count: each partition is assigned to a single consumer in the group, so with 6 partitions only 6 instances do work. To scale further you need more partitions (and keep key-ordering implications in mind) or faster processing per message."),
  m("cb32", "micro", "s",
    "A service saves an `Order` to SQL Server and then publishes `OrderCreated` to RabbitMQ. After a crash between the two steps, orders exist with no event. Which pattern fixes this dual-write problem?",
    ["Publish first and then save, so the event is never lost",
     "Transactional outbox: write the event to an outbox table in the same DB transaction, and a relay publishes it afterward",
     "Use a distributed transaction spanning SQL Server and RabbitMQ with publisher confirms",
     "Retry the publish three times inside the request before returning success"],
    1,
    "The outbox makes the state change and the intent to publish one atomic local commit, and a relay delivers it at least once (consumers must be idempotent). Publishing first just reverses the failure into events for orders that never existed, and RabbitMQ does not participate in XA/2PC transactions."),
  m("cb33", "micro", "s",
    "An order saga reserves stock, charges the card, then books shipping. Shipping fails after the payment has succeeded. What does saga compensation require?",
    ["Run compensating actions (refund the payment, release stock) that are idempotent and retryable",
     "Execute `ROLLBACK` on the database transactions of the earlier steps",
     "Retry shipping indefinitely, since compensation is only for crashes",
     "Delete the order, which cascades refunds to the payment service"],
    0,
    "Each saga step commits locally, so earlier steps cannot be rolled back and must instead be semantically undone by compensating transactions, which must be idempotent because they may be retried. Those earlier local transactions are already committed, so no `ROLLBACK` is possible."),
  m("cb34", "micro", "s",
    "A recommendations service is down. The calling service retries each failed call 3 times with 1-second delays; under load, its threads pile up and the caller itself becomes unresponsive. Which pattern best stops this cascade?",
    ["Increase the retry count so the call eventually succeeds",
     "Use a longer HTTP timeout so requests can wait for recovery",
     "Add a circuit breaker that fails fast while the dependency is unhealthy, with a fallback response",
     "Add more caller replicas so the retries are spread across more instances"],
    2,
    "Retries help with brief transient faults but amplify load against a dependency that is actually down; a circuit breaker opens after repeated failures, fails fast, frees threads, and probes for recovery. Longer timeouts hold threads even longer, and more replicas just add more retrying callers."),
  m("cb35", "micro", "m",
    "After a brief outage, 5,000 clients retry a failing API with fixed 2-second delays. Each wave of retries hits the recovering server at the same moment and knocks it over again. Which retry policy fixes this?",
    ["A shorter fixed delay so clients finish before the server fails",
     "Immediate retries with no delay so the outage ends sooner",
     "Unlimited retries so that every client eventually succeeds",
     "Exponential backoff with random jitter and a maximum retry count"],
    3,
    "Backoff spreads retries further apart as failures continue, and jitter desynchronizes clients so they do not arrive as a thundering herd; a cap prevents endless load. Fixed delays keep all clients in lockstep, and shorter or zero delays increase pressure on a recovering server."),
  m("cb36", "micro", "s",
    "A producer publishes 10,000 msgs/s while a consumer handles 2,000/s. The RabbitMQ queue grows and consumers buffer huge numbers of unacknowledged deliveries in memory. Which setting limits the in-flight work per consumer?",
    ["Enable `autoAck` so that unacknowledged messages cannot accumulate",
     "Set a consumer prefetch with `BasicQos` so the broker sends only N unacked messages at a time",
     "Raise the queue's `x-max-length` to 100 million messages",
     "Mark every message persistent using delivery mode 2"],
    1,
    "Prefetch (QoS) bounds how many unacknowledged messages the broker pushes to a consumer, which is the core backpressure control on the consuming side. It does not fix a sustained rate mismatch, so you still need more consumers or producer-side throttling; auto-ack removes the bound entirely."),
  m("cb37", "micro", "s",
    "A mobile client times out on `POST /payments` and retries, and the customer is charged twice. Which design makes the retry safe?",
    ["Client sends an `Idempotency-Key`; the server stores the key and outcome under a unique constraint and returns the stored result on repeats",
     "Change the endpoint to `PUT` because HTTP guarantees repeated calls are harmless",
     "Reject any payment of the same amount for the same user within the last minute",
     "Lower the client timeout so that fewer retries happen"],
    0,
    "An idempotency key lets the server recognize a repeat of the same logical request and return the original result, ideally recorded atomically with the payment via a unique constraint. HTTP method semantics are only conventions that the server must implement, and amount-based heuristics reject legitimate repeat purchases."),
  m("cb38", "micro", "j",
    "A team is placing an API gateway (for example YARP or Ocelot) in front of ten services. Which responsibility fits the gateway rather than the individual services?",
    ["Validating invoice totals and applying discount rules before forwarding the request",
     "Storing each service's data to avoid cross-service calls",
     "Routing, TLS termination, token validation and rate limiting at the edge",
     "Coordinating multi-step transactions across services with compensation"],
    2,
    "A gateway handles cross-cutting edge concerns such as routing, TLS, authentication and throttling in one place. Business rules belong in the owning services, and cross-service workflows belong in sagas or process managers, not in a gateway."),
  m("cb39", "micro", "m",
    "An ASP.NET Core service creates `new HttpClient()` inside a `using` block for every request. Under load it fails with `SocketException`, and netstat shows thousands of sockets in TIME_WAIT. What is the recommended fix?",
    ["Dispose the response messages explicitly after each call",
     "Register `HttpClient` as transient with `AddTransient<HttpClient>()`",
     "Increase the OS ephemeral port range and keep the pattern",
     "Use `IHttpClientFactory` (named or typed clients) so handlers and connections are pooled and recycled"],
    3,
    "Disposing an `HttpClient` per request leaves its sockets in TIME_WAIT and exhausts ports; `IHttpClientFactory` manages pooled `HttpMessageHandler` lifetimes (also refreshing DNS). Registering raw `HttpClient` as transient still creates a new handler each time, so the problem remains."),
  m("cb40", "micro", "s",
    "A Kafka consumer polls records, hands each one to a worker thread pool, and polls again, with `enable.auto.commit=true`. After a crash, some records were never processed even though their offsets were committed. Which approach gives at-least-once processing?",
    ["Set `auto.offset.reset=latest` so a restarted consumer resumes at the end",
     "Disable auto-commit and commit offsets only after the records have been processed successfully",
     "Commit offsets before processing so that records are never read twice",
     "Increase `max.poll.records` so that batches finish before the commit interval"],
    1,
    "Auto-commit commits positions on a timer regardless of whether asynchronous work has finished, so a crash can skip unprocessed records; committing after successful processing gives at-least-once (duplicates are possible, so handlers should be idempotent). Committing before processing is at-most-once, which is the behavior you are trying to remove."),
  m("cb41", "micro", "m",
    "After a monolith is split, a Reporting service needs orders joined with customer names, which are owned by two services with separate databases. A developer proposes a cross-database SQL join. What is the better approach?",
    ["Build a read model in Reporting fed by events (or compose through the services' APIs) instead of querying their databases",
     "Share a single database schema between the services so that joins keep working",
     "Give Reporting read-only credentials to both databases and use linked servers",
     "Copy the Customer service's code into Reporting so it can read the same tables"],
    0,
    "Each service owns its data and exposes it through contracts, so reporting needs should be met by API composition or a denormalized read model fed by events. Reaching into another service's tables couples schemas and deployments and defeats service autonomy."),
  m("cb42", "micro", "s",
    "A 7-step order workflow is implemented by choreography: each service reacts to the previous service's events. Now nobody can tell where an order is stuck, and adding a step means editing three services. Which change addresses this?",
    ["Replace the events with synchronous REST calls chained across all seven services",
     "Put all seven services' tables in one database so a single transaction covers them",
     "Use an orchestrator (a saga state machine) that owns the workflow state and sends commands to each step",
     "Add more consumers per queue so events move through the chain faster"],
    2,
    "Choreography spreads the flow implicitly across services, which makes tracking and changing long workflows hard; an orchestrator holds the process state in one place, at the cost of some central coupling. Chained synchronous calls and a shared database remove autonomy and add temporal coupling."),
  m("cb43", "micro", "j",
    "In RabbitMQ a queue is bound to a topic exchange with the binding key `orders.*.created`. Which routing key does this binding match?",
    ["`orders.created`",
     "`orders.eu.retail.created`",
     "`orders.eu`",
     "`orders.eu.created`"],
    3,
    "In topic bindings `*` matches exactly one word, so `orders.eu.created` matches. `orders.created` has no middle word and `orders.eu.retail.created` has two, which would need `#` (zero or more words) instead."),
  m("cb44", "micro", "s",
    "A team enables `enable.idempotence=true` on a Kafka producer and assumes the consumer's downstream database writes are now exactly-once. What is accurate?",
    ["Idempotence makes the consumer skip duplicates automatically via committed offsets",
     "It prevents duplicates caused by producer retries within a partition, but consumer-side effects still need idempotent handling or transactions",
     "It guarantees ordering across all partitions of the topic",
     "It only deduplicates when `acks=1`, and setting `acks=all` disables it"],
    1,
    "The idempotent producer uses producer ids and sequence numbers so broker-side retries do not write duplicates to a partition, and it requires `acks=all`. It says nothing about what a consumer does with the data afterward, so end-to-end exactly-once needs Kafka transactions or idempotent consumers."),

  // ---------- System design ----------
  m("cb45", "design", "m",
    "A cache-aside product cache is updated by writing the new price to the DB and then setting the cache key. Under concurrent updates, the cache can end up holding an older price than the database. Which update path is more robust?",
    ["Update the database, then delete the cache key so the next read repopulates it",
     "Update the cache first, then the database, so reads never miss",
     "Update the database and cache in parallel with `Task.WhenAll`",
     "Never invalidate and rely on a long TTL for correctness"],
    0,
    "Deleting the key after the database write avoids the interleaving where two writers set the cache in a different order than they committed, since the next reader reloads the current value (a TTL is still a good safety net). Writing the cache first or in parallel makes stale values easier, and relying only on a long TTL guarantees staleness."),
  m("cb46", "design", "s",
    "A very popular Redis key expires, and within the next second 3,000 requests miss and all hit the database to rebuild it, overloading it. What mitigates this cache stampede?",
    ["Use a shorter TTL so the cached value refreshes more often",
     "Switch to write-through so the cache can never miss on reads",
     "Let one request rebuild while others wait or serve the stale value (single-flight or lock), and add jitter to TTLs",
     "Add more database read replicas, which removes the cause of the stampede"],
    2,
    "Coalescing the rebuild into one caller (or serving stale-while-revalidate) prevents N identical expensive queries, and jittering TTLs keeps many keys from expiring together. A shorter TTL means more frequent stampedes, and replicas only add capacity to absorb the same redundant work."),
  m("cb47", "design", "s",
    "In a 12-node Redis Cluster, one celebrity profile key receives 40 percent of all reads. Its node saturates its CPU while the others idle, and adding nodes does not help. What addresses the hot key?",
    ["Add more shards so that the key is re-split across them",
     "Increase the number of hash slots to spread the key",
     "Switch to consistent hashing, which splits one key's value across nodes",
     "Replicate the hot key with a short-lived in-process cache, or keep N copies under suffixed keys read at random"],
    3,
    "A single key always maps to exactly one slot and node, so sharding cannot divide its traffic; the fix is to serve it from multiple places, such as local caches or key replicas, accepting brief staleness. Hashing schemes decide which node owns a key, but they never split one key."),
  m("cb48", "design", "s",
    "A multi-tenant orders table is range-sharded on an auto-incrementing `OrderId`, so all new writes hit the newest shard and it runs hot. Which statement about the alternative is accurate?",
    ["Hash-sharding by `OrderId` keeps range queries as cheap as before",
     "Hash-sharding spreads inserts evenly but makes range scans fan out to many shards",
     "Adding more range shards at the high end permanently solves the hotspot",
     "Sharding by `CreatedAt` instead removes the sequential write pattern"],
    1,
    "Hashing distributes sequential keys across shards, which fixes the write hotspot, but neighbouring ids no longer live together so range queries become scatter-gather. Range sharding on any monotonic value such as `CreatedAt` has the same newest-shard hotspot."),
  m("cb49", "design", "m",
    "A rate limiter allows 100 requests per minute using fixed windows aligned to the clock. A client sends 100 requests at 12:00:59 and another 100 at 12:01:00. What happened?",
    ["The client sent 200 requests within about a second because the counter reset at the boundary; sliding window or token bucket limits avoid this",
     "The limiter correctly blocked the second batch because 100 per minute was already used",
     "The limiter counted both batches in one window since requests are bucketed by arrival second",
     "A token bucket would behave identically to fixed windows here and also allow 200"],
    0,
    "Fixed windows reset counters at the boundary, so a client can burst up to twice the limit across two adjacent windows. A sliding window (or a token bucket with capacity 100) would throttle the second batch because tokens or recent history reflect the earlier burst."),
  m("cb50", "design", "j",
    "During a network partition, a replicated database node on the minority side cannot reach the majority. According to the CAP theorem, if it must stay consistent (linearizable), what must it do?",
    ["Keep accepting writes and reconcile with the majority later",
     "Serve reads from its local cache using a TTL",
     "Reject or delay requests until the partition heals, sacrificing availability on that side",
     "Promote itself to leader so that clients can continue"],
    2,
    "Under a partition you must choose between consistency and availability, and choosing consistency means the minority side cannot safely answer. Accepting writes or promoting itself risks divergent histories (split brain), and a TTL cache can return stale data."),
  m("cb51", "design", "m",
    "After adding asynchronous read replicas, users complain that right after posting a comment and being redirected, the comment is missing for about a second. What is the standard mitigation?",
    ["Use `NOLOCK` hints on replica reads so that uncommitted data is visible",
     "Increase the replica count so one is always up to date",
     "Cache the page in a CDN so the comment appears faster",
     "Read-your-writes routing: send that user's reads to the primary (or a replica past their write position) for a short window"],
    3,
    "Asynchronous replication means replicas lag, so a user can read a state older than their own write; routing that user's reads to the primary briefly (or to a sufficiently caught-up replica) restores read-your-writes. More replicas still lag, and a CDN can serve even staler content."),
  m("cb52", "design", "s",
    "A Dynamo-style store keeps N=3 replicas per key. With strict quorums, which configuration guarantees that a read sees the latest successful write?",
    ["`W=1`, `R=1`, since each write reaches at least one replica",
     "`W=2`, `R=2`, since `R + W > N` makes the read and write sets overlap",
     "`W=1`, `R=2`, since reading two replicas always includes the written one",
     "`W=2`, `R=1`, since a majority wrote and one reader is enough"],
    1,
    "When `R + W > N` any read quorum must share at least one replica with the latest write quorum, so it can find the newest version. `W=1,R=2` and `W=2,R=1` both sum to 3, which does not exceed N=3, so a read can miss the write."),
  m("cb53", "design", "m",
    "A flash sale causes 20x write spikes for five minutes. The database is sized for average load and times out. Orders may be acknowledged asynchronously. Which approach fits?",
    ["Queue-based load leveling: accept requests into a durable queue and let workers drain it at a rate the database sustains",
     "Raise the connection pool size and command timeout so all requests run at once",
     "Retry failed writes on the client immediately with no delay",
     "Switch to eventual consistency, which removes write capacity limits"],
    0,
    "A queue absorbs the burst and decouples arrival rate from processing rate, so the database works at a steady pace and the backlog drains after the spike. More connections and tight retries pile more concurrent work on the saturated database, and consistency settings do not create write capacity."),
  m("cb54", "design", "m",
    "A cache cluster picks a node with `hash(key) % N`. When a fifth node is added to a four-node cluster, nearly all keys map to different nodes and the hit rate collapses. What does consistent hashing change?",
    ["It maps every key to the same node to avoid misses",
     "It replicates every key to all nodes so that the node count no longer matters",
     "It never remaps any key when nodes are added",
     "It remaps only about 1/N of the keys when a node joins or leaves, instead of most keys"],
    3,
    "Consistent hashing places nodes and keys on a ring so adding or removing a node only moves the keys adjacent to it, roughly 1/N of them. Modulo hashing changes the divisor, so most keys move; consistent hashing does not eliminate remapping entirely, it minimizes it."),

  // ---------- Architecture and patterns ----------
  m("cb55", "rm-arch", "m",
    "In a Clean Architecture solution the `Domain` project references `Microsoft.EntityFrameworkCore` and its entities use EF-specific types. A reviewer flags it. Which principle is violated, and what is the fix?",
    ["Entities must live in the Presentation layer, which should own all persistence concerns",
     "Only the Application layer may use NuGet packages, so move the package reference there",
     "The dependency rule: inner layers must not depend on outer ones, so Domain defines abstractions and Infrastructure implements them with EF Core",
     "Clean Architecture forbids databases, so the repository should be replaced by an in-memory store"],
    2,
    "Dependencies point inward: the Domain and Application layers define interfaces, and Infrastructure (EF Core, messaging) implements them, so business rules do not depend on frameworks. The rule is about direction of dependency, not about banning packages or databases."),
  m("cb56", "rm-arch", "m",
    "A layered app has `Controllers/`, `Services/` and `Repositories/` folders. Adding a feature touches six files across folders, and services have grown into 2,000-line classes. What does vertical slice architecture change?",
    ["It merges all layers into one project with no abstractions allowed",
     "It organizes code by feature, where each request has its own handler, validation and data access so changes stay in one place",
     "It requires each feature to be deployed as its own microservice",
     "It forces every slice to use the same repository pattern for consistency"],
    1,
    "Vertical slices group everything a use case needs together, so a change touches one folder and each slice can choose its own approach (for example EF directly for a query). It is a code organization style, not a deployment model, and it does not mandate shared repositories."),
  m("cb57", "rm-arch", "s",
    "A team claims that CQRS requires separate read and write databases and event sourcing. A senior engineer disagrees. Which statement is accurate?",
    ["CQRS only separates command (write) and query (read) models; one database is fine and event sourcing is optional",
     "CQRS requires event sourcing, otherwise the read model cannot be built",
     "CQRS requires a message broker between the command and query sides",
     "CQRS means every query must go to a replica and never to the primary"],
    0,
    "CQRS is the separation of the model that changes state from the model that reads it; it can be as simple as separate handlers over the same database, and the two sides may later get separate stores or projections if needed. Event sourcing and CQRS are often combined but neither requires the other."),
  m("cb58", "rm-arch", "s",
    "In an event-sourced `Account` aggregate, a `FundsWithdrawn` event for 500 was recorded by mistake and has been replayed into projections. How should it be corrected?",
    ["Update the stored event to 50 so that replays give the right balance",
     "Delete the event and rebuild all projections",
     "Truncate the stream and replay from the latest snapshot",
     "Append a compensating event (for example `WithdrawalReversed`), since the event log is append-only and immutable"],
    3,
    "Events are facts about what happened, so mistakes are corrected by appending new events that reverse or adjust the effect, preserving the audit trail and consistency for consumers who already saw the original. Editing or deleting history breaks projections and anything downstream that already processed the event."),
  m("cb59", "rm-arch", "j",
    "A service has an `IProductRepository`, and you want to add caching without modifying the repository or its callers. Which pattern fits?",
    ["Singleton: ensure only one repository instance exists",
     "Factory Method: let subclasses choose the repository",
     "Decorator: wrap it in a `CachedProductRepository` that implements the same interface and delegates to the original",
     "Observer: notify the cache whenever the repository is called"],
    2,
    "A decorator implements the same interface, adds behavior (caching) around the inner object, and can be registered in dependency injection without changing callers. Singleton and Factory Method address instance creation, not adding behavior around an existing object."),
  m("cb60", "rm-arch", "j",
    "An `if/else` chain picks a discount algorithm by customer tier and grows with every new tier, violating the open/closed principle. Which pattern cleanly replaces it?",
    ["Singleton, so that only one discount calculator exists",
     "Strategy: put each algorithm behind `IDiscountStrategy` and select the implementation by tier",
     "Adapter, to convert tiers into discount objects",
     "Facade, so callers see one `Discount()` method with the same chain inside"],
    1,
    "Strategy encapsulates interchangeable algorithms behind one interface, so adding a tier means adding a class rather than editing a conditional. A facade only hides the same chain behind a simpler entry point and does not remove the branching."),
  m("cb61", "rm-arch", "s",
    "Eight 'microservices' must be deployed together, share one database, and a single user request triggers a synchronous chain through five of them. What best describes this system?",
    ["A well-factored microservice architecture with strong cohesion",
     "A modular monolith, since the modules share a database",
     "An event-driven architecture, because the services communicate",
     "A distributed monolith, with the coupling of a monolith plus the network failure modes of distribution"],
    3,
    "Services that cannot be deployed independently, share a database and call each other synchronously in chains have the downsides of both styles. A modular monolith would keep modules in one process with clear boundaries and no network hops between them, and synchronous request chains are not event-driven."),
  m("cb62", "rm-arch", "s",
    "An Orders service needs customer emails. Calling Customers synchronously on each event creates runtime coupling, so Customers instead publishes `CustomerUpdated` events carrying the email and Orders keeps a local copy. What is the main trade-off?",
    ["Runtime coupling is reduced, but the local copy is eventually consistent and may be stale, and Orders now stores data it does not own",
     "The local copy is always strongly consistent with Customers, but publishing is slower",
     "Orders can no longer work when Customers is down, so availability falls",
     "It removes the need for any contract, so event schemas can change freely"],
    0,
    "Event-carried state transfer lets Orders keep working when Customers is unavailable, at the price of replicas that lag behind and duplicated data that must be kept up to date from events. The event schema is still a contract between services, so changes must be versioned.")
];
